 <path d="M385,90 C372,120 352,150 346,170 C340,200 334,230 331,252 C290,258 230,258 187,256 C150,300 112,350 83,395" fill="none" stroke="#EEF3EA" stroke-width="1.6" stroke-dasharray="6 6"/>
