 <g transform="translate(346,75)"><circle r="11" fill="#FBFCF8" stroke="#3E7A86" stroke-width="1.5"/><path d="M-5,1 L5,-4 L6,-3 L1,1 L4,4 L3,5 L-1,3 L-4,4 Z" fill="#3E7A86"/></g>
