function localMap(id){const L=PLACES[id].local;const pts=L.pts.map(p=>{const[n,x,y,t]=p;let mk;
 if(t==='obj')mk=`<circle cx="${x}" cy="${y}" r="14" fill="#E3B39A" fill-opacity=".3"/><circle cx="${x}" cy="${y}" r="7" fill="#E3B39A" stroke="#FBFCF8" stroke-width="2"/>`;
 else if(t==='st')mk=`<rect x="${x-6}" y="${y-6}" width="12" height="12" rx="3" fill="#FBFCF8" stroke="#1F4D38" stroke-width="1.6"/>`;
 else if(t==='air')mk=`<circle cx="${x}" cy="${y}" r="8" fill="#FBFCF8" stroke="#3E7A86" stroke-width="1.6"/>`;
 else if(t==='park')mk=``;else mk=`<circle cx="${x}" cy="${y}" r="5" fill="#1F4D38"/>`;
 return `${mk}<text x="${x+(t==='park'?0:12)}" y="${y+(t==='park'?0:4)}" text-anchor="${t==='park'?'middle':'start'}" font-family="${t==='park'?'Montserrat':'Comfortaa'}" font-weight="${t==='park'?300:700}" font-size="${t==='park'?12:11.5}" fill="${t==='park'?'#1F4D38':'#1E2722'}">${n}</text>`}).join('');
 let streets='';[[0,120,480,170],[60,0,140,440],[0,300,480,250],[260,0,230,440],[0,210,480,220],[360,0,420,440]].forEach(s=>streets+=`<line x1="${s[0]}" y1="${s[1]}" x2="${s[2]}" y2="${s[3]}" stroke="#FBFCF8" stroke-width="6"/>`);
 return `<svg viewBox="0 0 420 320" role="img" aria-label="Схема: ${PLACES[id].name} внутри"><rect width="420" height="320" fill="#E6EDE1"/>${streets}<path d="${L.park}" fill="#CFDDC9"/><path d="${L.river}" fill="none" stroke="#3E7A86" stroke-opacity=".5" stroke-width="3"/>${pts}<text x="404" y="306" text-anchor="end" font-family="Montserrat" font-weight="300" font-size="9.5" fill="#6E7571">схема без масштаба</text></svg>`}
