/* ===== Эффекты: плавный скролл, тактильность, звук природы, параллакс ===== */
const RM=matchMedia('(prefers-reduced-motion: reduce)'),MOB=matchMedia('(max-width: 900px)');
function smoothB(){return RM.matches?'auto':'smooth'}
const ls={get:k=>{try{return localStorage.getItem(k)}catch(e){return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}}};
const isQuiet=()=>ls.get('bio-quiet')==='1';

// 2. Тактильность (на iOS Vibration API нет — вызов просто пропускается)
const buzz=p=>{if(!isQuiet()&&'vibrate' in navigator)try{navigator.vibrate(p)}catch(e){}};
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('.btn,.chip'))buzz([10,30])});
const secIdx=()=>{let k=0;$$('#app>section,#app>figure').forEach((s,i)=>{if(s.getBoundingClientRect().top<innerHeight*.4)k=i});return k};
let swFrom=0;
addEventListener('touchstart',()=>{swFrom=secIdx()},{passive:true});
addEventListener('touchend',()=>setTimeout(()=>{if(secIdx()!==swFrom)buzz([8,40,8])},450),{passive:true});

// 4. Параллакс фона hero (выключен на мобильных и при prefers-reduced-motion)
const PXK=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--px-k'))||.3;let pxTick=false;
function parallax(){pxTick=false;const off=RM.matches||MOB.matches;
 $$('.fullhero>img,.hero .ph img').forEach(im=>{if(off){im.style.transform='';return}
  const box=im.parentNode,h=box.offsetHeight,y=scrollY*PXK;if(box.getBoundingClientRect().bottom<0)return;
  if(box.classList.contains('fullhero'))im.style.transform=`translate3d(0,${y}px,0)`;
  else{const m=h*.07;im.style.transform=`translate3d(0,${Math.min(y,2*m)-m}px,0) scale(1.15)`}})}
const pxReq=()=>{if(!pxTick){pxTick=true;requestAnimationFrame(parallax)}};
addEventListener('scroll',pxReq,{passive:true});addEventListener('resize',pxReq);addEventListener('popstate',()=>setTimeout(pxReq,80));
[RM,MOB].forEach(m=>m.addEventListener&&m.addEventListener('change',pxReq));document.addEventListener('DOMContentLoaded',pxReq);

// Появление блоков при скролле: CSS scroll-driven, а где его нет — IntersectionObserver
if(!(window.CSS&&CSS.supports&&CSS.supports('animation-timeline','view()'))){document.documentElement.classList.add('no-sda');
 const rio='IntersectionObserver' in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');rio.unobserve(e.target)}}),{rootMargin:'0px 0px -8% 0px'}):null;
 const rvScan=()=>{if(!rio)return;$$('#app .sh,#app .card,#app .jfeat,#app .vsteps>*,#app .team>*,#app .facts>*,#app .chap>h2').forEach(el=>{if(!el.classList.contains('rvx')){el.classList.add('rvx');rio.observe(el)}})};
 addEventListener('popstate',()=>setTimeout(rvScan,30));document.addEventListener('DOMContentLoaded',()=>setTimeout(rvScan,30))}

if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
